import os, json, numpy as np, sys
sys.path.append('storage/noesis')
try:
    from validate_packing import load_saved_best, validate, write_report
except Exception:
    load_saved_best = None
    validate = None
    write_report = None

N = 26

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    r_hole = d - r0 - eps
    return np.array(centers, float), np.array([r0]*25 + [r_hole], float)

def construct_packing():
    # Load saved best or fallback to constructive seed
    if load_saved_best is not None:
        c, r = load_saved_best()
    else:
        c, r = None, None
    if c is None:
        c, r = grid_plus_hole_seed()

    # Audit and write report
    if validate is not None and write_report is not None:
        rep = validate(c, r, tol_violate=1e-12, tol_near=1e-8)
        write_report(rep, path='storage/noesis/exports/validation_report.json')

    return c.astype(float), r.astype(float)
